// Generated by iso. Honours Railway's PORT contract on Lambda Web Functions.
// The runtime tells us where to listen via AWS_LAMBDA_HTTP_ENDPOINT ("0.0.0.0:3000");
// Railway apps read process.env.PORT. We set PORT, then import the user's entry file untouched.
import { pathToFileURL } from "node:url";
import { createRequire } from "node:module";
import path from "node:path";

const ep = process.env.AWS_LAMBDA_HTTP_ENDPOINT || "0.0.0.0:3000";
const port = ep.split(":").pop();
process.env.PORT = process.env.PORT && process.env.PORT === port ? process.env.PORT : port;
process.env.HOST = "0.0.0.0";
if (!process.env.NODE_ENV) process.env.NODE_ENV = "production";
process.chdir(path.dirname(new URL(import.meta.url).pathname));

const ORIGIN_SECRET = process.env.ISO_ORIGIN_SECRET;
if (ORIGIN_SECRET) {
  // Custom domain via CloudFront: reject requests that bypass the distribution.
  const http = await import("node:http");
  const orig = http.Server.prototype.emit;
  http.Server.prototype.emit = function (ev, req, res) {
    if (ev === "request" && req?.headers && req.headers["x-iso-origin-secret"] !== ORIGIN_SECRET && !req.headers["x-iso-internal"]) {
      res.statusCode = 403; res.end("direct access not allowed"); return true;
    }
    return orig.apply(this, arguments);
  };
}

const entry = "__ENTRY__";
if (/\.(cjs)$/.test(entry)) {
  createRequire(import.meta.url)(path.resolve(entry));
} else {
  await import(pathToFileURL(path.resolve(entry)).href);
}
